import { createMinimalEvent } from "./EventTest";
import { RedactionEvent } from "../../../src";
import { expectArrayEquals } from "../../TestUtils";

describe("RedactionEvent", () => {
    it("should support CS-v2 format redactions", () => {
        const ev = createMinimalEvent();
        ev['redacts'] = '$example';
        const obj = new RedactionEvent(ev);

        expect(obj.redactsEventId).toEqual(ev['redacts']);
        expectArrayEquals([ev['redacts']], obj.redactsEventIds);
    });

    it("should support MSC2174 format redactions", () => {
        const ev = createMinimalEvent();
        ev.content['redacts'] = '$example';
        const obj = new RedactionEvent(ev);

        expect(obj.redactsEventId).toEqual(ev.content['redacts']);
        expectArrayEquals([ev.content['redacts']], obj.redactsEventIds);
    });

    it("should support MSC2244 format redactions", () => {
        const ev = createMinimalEvent();
        ev.content['redacts'] = ['$example', '$another'];
        const obj = new RedactionEvent(ev);

        expect(obj.redactsEventId).toEqual(ev.content['redacts'][0]);
        expectArrayEquals(ev.content['redacts'], obj.redactsEventIds);
    });
});

import { RoomEvent } from "./RoomEvent";

/**
 * The content definition for m.room.redaction events
 * @category Matrix event contents
 * @see RedactionEvent
 */
export interface RedactionEventContent {
    /**
     * The event ID or IDs this event redacts.
     */
    redacts?: string | string[]; // MSC2174 & MSC2244
}

/**
 * Represents an m.room.redaction room event
 * @category Matrix events
 */
export class RedactionEvent extends RoomEvent<RedactionEventContent> {
    constructor(event: any) {
        super(event);
    }

    /**
     * The event ID this event redacts.
     * @deprecated It is possible for multiple events to be redacted depending on the room version.
     */
    public get redactsEventId(): string {
        return this.redactsEventIds[0];
    }

    /**
     * The event IDs this event redacts.
     */
    public get redactsEventIds(): string[] {
        if (Array.isArray(this.content.redacts)) {
            return this.content.redacts;
        } else if (this.content.redacts) {
            return [this.content.redacts];
        } else {
            return [this.event['redacts']];
        }
    }
}

/**
 * Information about the policies (terms of service) a server may have.
 * @category Models
 */
export interface Policies {
    policies: {
        [id: string]: Policy;
    };
}

/**
 * Information about a policy (terms of service) a server may have.
 * @category Models
 */
export interface Policy {
    version: string;

    [language: string]: TranslatedPolicy | string; // "|string" is required for `version` to work
}

/**
 * Information about a (translated) policy (terms of service).
 * @category Models
 */
export interface TranslatedPolicy {
    name: string;
    url: string;
}

import { MatrixAuth } from "../src";
import { createTestClient, HttpBackend } from "./TestUtils";

export function createTestAuth(): { auth: MatrixAuth, http: HttpBackend, hsUrl: string } {
    const result = createTestClient();

    const mxClient = result.client;
    const hsUrl = result.hsUrl;
    const http = result.http;

    const auth = new MatrixAuth(hsUrl);

    // Overwrite the function for which client to return. We want to use the
    // one which uses our http thing.
    auth['createTemplateClient'] = () => mxClient;

    return { hsUrl, http, auth };
}

describe('MatrixAuth', () => {
    describe('passwordRegister', () => {
        it('should call the right endpoint', async () => {
            const { auth, http, hsUrl } = createTestAuth();

            const username = "testing_username";
            const password = "P@ssw0rd";
            const accessToken = "1234";

            http.mock.intercept({
                method: "POST",
                path: "/_matrix/client/v3/register",
            }).reply(200, (opts) => {
                expect(JSON.parse(opts.body as string)).toMatchObject({ username, password });
                return { access_token: accessToken };
            });

            const [client] = await Promise.all([auth.passwordRegister(username, password), http.flushAllExpected()]);
            expect(client.homeserverUrl).toEqual(hsUrl);
            expect(client.accessToken).toEqual(accessToken);
        });

        // TODO: Enable test.
        // We can't test this currently because matrix-mock-request doesn't support sending the response
        // object for errors.

        xit('should support UIA', async () => {
            const { auth, http, hsUrl } = createTestAuth();

            const username = "testing_username";
            const password = "P@ssw0rd";
            const accessToken = "1234";
            const sessionId = "5678";

            // First is UIA
            http.mock.intercept({
                method: "POST",
                path: "/_matrix/client/v3/register",
            }).reply(401, (opts) => {
                expect(JSON.parse(opts.body as string)).toMatchObject({ username, password });
                return {
                    session: sessionId,
                    flows: [
                        { stages: ["m.login.dummy"] },
                    ],
                    params: {},
                };
            });
            http.mock.intercept({
                method: "POST",
                path: "/_matrix/client/v3/register",
            }).reply(200, (opts) => {
                expect(JSON.parse(opts.body as string)).toMatchObject({
                    username,
                    password,
                    auth: {
                        type: "m.login.dummy",
                        session: sessionId,
                    },
                });
                return { access_token: accessToken };
            });

            const [client] = await Promise.all([auth.passwordRegister(username, password), http.flushAllExpected()]);
            expect(client.homeserverUrl).toEqual(hsUrl);
            expect(client.accessToken).toEqual(accessToken);
        });
    });

    describe('passwordLogin', () => {
        it('should call the right endpoint', async () => {
            const { auth, http, hsUrl } = createTestAuth();

            const username = "testing_username";
            const password = "P@ssw0rd";
            const accessToken = "1234";

            http.mock.intercept({
                method: "POST",
                path: "/_matrix/client/v3/login",
            }).reply(200, (opts) => {
                expect(JSON.parse(opts.body as string)).toMatchObject({
                    type: "m.login.password",
                    identifier: {
                        type: "m.id.user",
                        user: username,
                    },
                    password,
                });
                return { access_token: accessToken };
            });

            const [client] = await Promise.all([auth.passwordLogin(username, password), http.flushAllExpected()]);
            expect(client.homeserverUrl).toEqual(hsUrl);
            expect(client.accessToken).toEqual(accessToken);
        });
    });
});

import { IStorageProvider, MatrixClient, MSC2380MediaInfo, UnstableApis } from "../src";
import { createTestClient, HttpBackend } from "./TestUtils";

export function createTestUnstableClient(
    storage: IStorageProvider = null,
): {
    client: UnstableApis;
    mxClient: MatrixClient;
    http: HttpBackend;
    hsUrl: string;
    accessToken: string;
} {
    const result = createTestClient(storage);
    const mxClient = result.client;
    const client = new UnstableApis(mxClient);

    delete result.client;

    return { ...result, client, mxClient };
}

describe('UnstableApis', () => {
    describe('getRoomAliases', () => {
        it('should call the right endpoint', async () => {
            const { client, http, hsUrl } = createTestUnstableClient();

            const aliases = ["#test:example.org", "#test2:example.org"];
            const roomId = "!room:example.org";

            http.mock.intercept({
                method: "GET",
                path: `/_matrix/client/unstable/org.matrix.msc2432/rooms/${encodeURIComponent(roomId)}/aliases`,
            }).reply(200, { aliases: aliases });

            const [result] = await Promise.all([client.getRoomAliases(roomId), http.flushAllExpected()]);
            expect(result).toMatchObject(aliases);
        });
    });

    describe('addReactionToEvent', () => {
        it('should send an m.reaction event', async () => {
            const { client, http, hsUrl } = createTestUnstableClient();

            const roomId = "!test:example.org";
            const originalEventId = "$orig:example.org";
            const newEventId = "$new:example.org";
            const emoji = "😀";
            const expectedReaction = {
                "m.relates_to": {
                    event_id: originalEventId,
                    key: emoji,
                    rel_type: "m.annotation",
                },
            };

            http.mock.intercept({
                method: "PUT",
                path: new RegExp(`^/_matrix/client/v3/rooms/${encodeURIComponent(roomId)}/send/m.reaction/`),
            }).reply(200, (opts) => {
                expect(JSON.parse(opts.body as string)).toMatchObject(expectedReaction);
                return { event_id: newEventId };
            });

            const [result] = await Promise.all([client.addReactionToEvent(roomId, originalEventId, emoji), http.flushAllExpected()]);
            expect(result).toEqual(newEventId);
        });
    });

    describe('getRelationsForEvent', () => {
        test.each([
            [null, null],
            ['org.example.relation', null],
            ['org.example.relation', 'org.example.event_type'],
        ])("should call the right endpoint for rel=%p and type=%p", async (relType, eventType) => {
            const { client, http, hsUrl } = createTestUnstableClient();

            const roomId = "!room:example.org";
            const eventId = "$event";
            const response = {
                chunk: [
                    { eventContents: true },
                    { eventContents: true },
                    { eventContents: true },
                ],
            };

            const relTypeComponent = relType ? `/${encodeURIComponent(relType)}` : '';
            const eventTypeComponent = eventType ? `/${encodeURIComponent(eventType)}` : '';
            http.mock.intercept({
                method: "GET",
                path: `/_matrix/client/unstable/rooms/${encodeURIComponent(roomId)}/relations/${encodeURIComponent(eventId)}${relTypeComponent}${eventTypeComponent}`,
            }).reply(200, response);

            const [result] = await Promise.all([client.getRelationsForEvent(roomId, eventId, relType, eventType), http.flushAllExpected()]);
            expect(result).toEqual(response);
        });
    });

    describe('getMediaInfo', () => {
        it('should call the right endpoint', async () => {
            const { client, http, hsUrl } = createTestUnstableClient();

            const domain = "example.org";
            const mediaId = "abc123";
            const mxc = `mxc://${domain}/${mediaId}`;
            const response: MSC2380MediaInfo = {
                content_type: "image/png",
                size: 12,
            };

            http.mock.intercept({
                method: "GET",
                path: `/_matrix/media/unstable/info/${encodeURIComponent(domain)}/${encodeURIComponent(mediaId)}`,
            }).reply(200, response);

            const [result] = await Promise.all([client.getMediaInfo(mxc), http.flushAllExpected()]);
            expect(result).toEqual(response);
        });

        test.each([
            ["invalid", "'mxcUrl' does not begin with mxc://"],
            ["mxc://", "Missing domain or media ID"],
            ["mxc://domainonly", "Missing domain or media ID"],
            ["mxc://emptymedia/", "Missing domain or media ID"],
        ])("should fail if the MXC URI is invalid: %p / %p", async (val, err) => {
            const { client } = createTestUnstableClient();

            await expect(client.getMediaInfo(val)).rejects.toThrow(err);
        });
    });
});

