    describe('listAllUsers', () => {
        it('should call the right endpoint', async () => {
            const { client, http, hsUrl } = createTestSynapseAdminClient();

            const user1 = {
                name: "@someone:example.org",
                displayname: "foobar",
                avatar_url: "mxc://example.org/animage",
                admin: 1,
                deactivated: 0,
                is_guest: 0,
                user_type: null,
                password_hash: "$hashbrown",
            };

