                name: "@else:example.org",
                displayname: "barbaz",
                avatar_url: "mxc://example.org/animage2",
                admin: 1,
                deactivated: 0,
                is_guest: 0,
                user_type: null,
                password_hash: "$mmmm-hashbrown",
            };

            const request = {
                limit: 1,
                name: "bar",
                guests: true,
